on conflict (id) do nothing;
insert into public.wd_chunks (id, document_id, chunk_index, section, content, char_start, char_end, word_count, excerpt_sha256, source_anchor, original_source_locator, content_type, embedding, embedding_model, embedding_dimensions)
select r.id, r.document_id, r.chunk_index, r.section, r.content, r.char_start, r.char_end, r.word_count, r.excerpt_sha256, r.source_anchor, r.original_source_locator, r.content_type, r.embedding, r.embedding_model, r.embedding_dimensions
from jsonb_populate_recordset(null::public.wd_chunks, $corpus$[{"id": "164e98b3-5ffe-5ef2-b324-c5ee3aa6f853", "document_id": "dc8afda4-1ac7-58b4-98e1-644c1cfd2dc3", "chunk_index": 0, "section": "Scope", "content": "The demo assistant explains documented product facts, internal research rules, and general tax context. It cannot select an investment for a named client, authorise an exception, place an order, or determine personal tax liability. Personalised requests must use the qualified advisory process.", "char_start": 170, "char_end": 464, "word_count": 42, "excerpt_sha256": "504eb685bcfe011254604eaa2350883bbeb907ee8ee8ee2c1f559e824fbb7bc7", "source_anchor": "documents/demo/demo_policy.md#scope", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "340beeb6-887a-5bb7-841a-20f36f428869", "document_id": "dc8afda4-1ac7-58b4-98e1-644c1cfd2dc3", "chunk_index": 1, "section": "Required context", "content": "Before stating a product-specific condition, identify the exact product ID, class, jurisdiction, and relevant date. Ask for decisive missing information instead of silently assuming it. Do not collect account numbers, PAN, contact details, or portfolios in the demo.", "char_start": 487, "char_end": 753, "word_count": 38, "excerpt_sha256": "520804ceb5a113a880061bfd1c2f80fd9db3f80fcd1c38dff786ff5512bc76c4", "source_anchor": "documents/demo/demo_policy.md#required-context", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "a3a81bf3-67df-5117-9e98-250e5dbd7170", "document_id": "dc8afda4-1ac7-58b4-98e1-644c1cfd2dc3", "chunk_index": 2, "section": "Evidence and authority", "content": "Use the controlling product terms for charges and redemption conditions. Brochure marketing text cannot waive a controlling restriction. Use applicable dates, not upload order, to select a version. Equal-authority conflicting statements require escalation; do not average or choose whichever was retrieved first.", "char_start": 782, "char_end": 1094, "word_count": 42, "excerpt_sha256": "a6ec6646f42d4b060ecd257c81ce2ff3a08914df7006a58267895fd3f0dc3ba3", "source_anchor": "documents/demo/demo_policy.md#evidence-and-authority", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "c9ee128e-6a5b-56fd-9e4c-602661118d8a", "document_id": "dc8afda4-1ac7-58b4-98e1-644c1cfd2dc3", "chunk_index": 3, "section": "Source review", "content": "Every material claim must identify its document version and section. The relationship manager should inspect the cited passage and its exceptions. Supported evidence is not proof of client suitability. Copying an answer must preserve citations, scope, dates, and the demo notice.", "char_start": 1114, "char_end": 1393, "word_count": 41, "excerpt_sha256": "81ba151d95b8e4a13804f8a2eda72ffc3100271ac156e61435597ce446c1567e", "source_anchor": "documents/demo/demo_policy.md#source-review", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "17080df5-3b7a-53a5-9d6e-a3178d2f34c7", "document_id": "a484e906-234f-58a6-9265-14d9669b36b4", "chunk_index": 0, "section": "Product identity", "content": "This fictional product has ID DEMO-HIF-A. It is a market-linked income fund for illustration only. No principal or return is guaranteed. These version 1 terms apply from 1 January 2026 through 30 June 2026 inclusive; version 2 applies to new acquisitions from 1 July 2026.", "char_start": 187, "char_end": 459, "word_count": 45, "excerpt_sha256": "31f247ca1a9ca177a0287c9d057df67a1d649a831e5425ea7b6899d5f925f223", "source_anchor": "documents/demo/horizon_a_v1.md#product-identity", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "c8d58153-692e-5376-8bbf-ad0c1680ec67", "document_id": "a484e906-234f-58a6-9265-14d9669b36b4", "chunk_index": 1, "section": "Redemption charges", "content": "For units acquired under version 1, an illustrative exit charge of 1.00% applies to the redeemed amount when redemption is requested within 90 calendar days after acquisition. The charge is zero after that window. Each acquisition lot has its own date; the redemption request date alone does not select the terms.", "char_start": 484, "char_end": 797, "word_count": 51, "excerpt_sha256": "83378e93d27595ac0f73b72623b601d2b13faa7ef8f8604e67271c610d55886e", "source_anchor": "documents/demo/horizon_a_v1.md#redemption-charges", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "277063be-e5b7-57eb-9ecb-178c5fe98041", "document_id": "a484e906-234f-58a6-9265-14d9669b36b4", "chunk_index": 2, "section": "Other attributes", "content": "The illustrative annual ongoing charge is 0.80%; it is separate from the exit charge. There is no fixed lock-in, but processing is subject to complete instructions and operational review. No minimum investment or settlement guarantee is provided in this fixture.", "char_start": 820, "char_end": 1082, "word_count": 40, "excerpt_sha256": "bde229ab702d775d457d605da5c9f8742c185b72456cbebe859205e3c74d310c", "source_anchor": "documents/demo/horizon_a_v1.md#other-attributes", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "dd7ee678-60d7-55d5-bacd-6484911a8df8", "document_id": "778a1441-e293-58a1-820d-f27408346695", "chunk_index": 0, "section": "Product identity", "content": "This fictional product has ID DEMO-HIF-A. It is market-linked and carries potential principal loss. Version 2 applies only to acquisitions from 1 July 2026 onwards. Acquisitions before that date remain governed by version 1; ask for acquisition date when a holding spans versions.", "char_start": 187, "char_end": 467, "word_count": 43, "excerpt_sha256": "44f2b592b9c430af9f0634667d634a1b570d2a890dca2133a2efdf614e00650d", "source_anchor": "documents/demo/horizon_a_v2.md#product-identity", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "2187bd41-d73e-5e8d-95ea-d64c8d9d8b08", "document_id": "778a1441-e293-58a1-820d-f27408346695", "chunk_index": 1, "section": "Redemption charges and exception", "content": "For an acquisition governed by version 2, an illustrative exit charge of 0.50% applies to the redeemed amount if the request occurs within 30 calendar days after acquisition. The charge is zero after that window. Within the 30-day window, a verified duplicate-allotment correction is exempt only after written approval from Demo Product Operations. A relationship manager cannot grant the exemption.", "char_start": 506, "char_end": 905, "word_count": 60, "excerpt_sha256": "462312ddc36db1c97718e9a6b8b350b94c92dfe519da80d5f9fbb475cb97ca67", "source_anchor": "documents/demo/horizon_a_v2.md#redemption-charges-and-exception", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "03105ce7-6a3b-5224-89fc-ec8cbb13f4e9", "document_id": "778a1441-e293-58a1-820d-f27408346695", "chunk_index": 2, "section": "Other attributes", "content": "The illustrative annual ongoing charge is 0.80% and is separate from the exit charge. There is no fixed lock-in. Redemption processing requires complete instructions and operational review. This document does not guarantee settlement timing or tax treatment.", "char_start": 928, "char_end": 1186, "word_count": 37, "excerpt_sha256": "eaf94525b26cbce75dc3aa2a86e6362ff579ac0c9ee750d1c0bc00f117fc0c27", "source_anchor": "documents/demo/horizon_a_v2.md#other-attributes", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "d0016cd3-ea7b-559a-a0af-7397d33101a8", "document_id": "0e7a47d6-bfbe-5df2-bd57-07e75e1dbbeb", "chunk_index": 0, "section": "Product identity", "content": "This fictional class has ID DEMO-HIF-B. Its terms must not be mixed with DEMO-HIF-A. It is a market-linked product, and principal and returns are not guaranteed.", "char_start": 177, "char_end": 338, "word_count": 26, "excerpt_sha256": "055e0a8922f3882de7c751bb88b523f112194edee5c11e851bfea905b35f8062", "source_anchor": "documents/demo/horizon_b.md#product-identity", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "5dd297dd-ad30-55b8-a390-b1d48c1b965f", "document_id": "0e7a47d6-bfbe-5df2-bd57-07e75e1dbbeb", "chunk_index": 1, "section": "Charges and liquidity", "content": "The illustrative annual ongoing charge is 1.10%. An illustrative exit charge of 1.00% applies within 180 calendar days of each acquisition and is zero afterwards. There is no fixed lock-in. Full redemption conditions require operational review. No minimum investment or settlement date is provided.", "char_start": 366, "char_end": 664, "word_count": 44, "excerpt_sha256": "b49b8ef7787ee0ec640b655bf4e14b2513221538546880bd2e25cfd2cdb8ae3b", "source_anchor": "documents/demo/horizon_b.md#charges-and-liquidity", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "16ed05b9-463a-53ad-b793-3a581f2e4230", "document_id": "0e7a47d6-bfbe-5df2-bd57-07e75e1dbbeb", "chunk_index": 2, "section": "Comparison boundary", "content": "Compare only documented attributes. A missing value is not zero. A lower charge does not establish that one class is suitable or superior. A class-specific exception must have evidence for that exact class.", "char_start": 690, "char_end": 896, "word_count": 33, "excerpt_sha256": "fd49f2d50db7843ba84849ab49843d71bd0f032385f8559a45a546e3eace9818", "source_anchor": "documents/demo/horizon_b.md#comparison-boundary", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "099bb7d9-6b6b-5ccf-8711-e13407291ad2", "document_id": "29616dc4-8261-5698-a374-b04aad2ce3cc", "chunk_index": 0, "section": "Product identity", "content": "This fictional product has ID DEMO-EGF-G. It is a market-linked growth product with potential loss of principal and no guaranteed return.", "char_start": 171, "char_end": 308, "word_count": 21, "excerpt_sha256": "5a9dba4d6eb4ba15a4908c35b4149743e04ac4739ac728d4a5b9b772fbbe5989", "source_anchor": "documents/demo/evergreen.md#product-identity", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "96697479-de1d-5483-96fd-3737a54fd1b1", "document_id": "29616dc4-8261-5698-a374-b04aad2ce3cc", "chunk_index": 1, "section": "Charges and lock-in", "content": "The illustrative annual ongoing charge is 1.20%. Each acquisition has a fictional 180-calendar-day lock-in. A redemption request before the lock-in ends cannot be processed. After the lock-in, the exit charge is zero. No emergency exception is authorised in this fixture. These are invented product terms, not ELSS legislation.", "char_start": 334, "char_end": 661, "word_count": 48, "excerpt_sha256": "ec3389fcbe9fe5a4d598351a66274933b08aba5b4a3e68a8b4273a06125a858f", "source_anchor": "documents/demo/evergreen.md#charges-and-lock-in", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "61034555-696f-5a77-922b-920de39e850d", "document_id": "29616dc4-8261-5698-a374-b04aad2ce3cc", "chunk_index": 2, "section": "Missing information", "content": "Minimum investment, settlement time, historical performance, and personal tax outcomes are not supplied. Do not infer them from the product name or from another product.", "char_start": 687, "char_end": 856, "word_count": 25, "excerpt_sha256": "1f38244b6067a20210f9c800477ac568c7db5ac1e8f4d85e12b3904ab1672b9a", "source_anchor": "documents/demo/evergreen.md#missing-information", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "4528bbd8-5fa3-58ca-bd09-d3badb7c40f6", "document_id": "b0d468a5-e393-5621-8e32-997dc8c47118", "chunk_index": 0, "section": "Information needed", "content": "For a fund-sale question, ask for jurisdiction, tax-residency category, exact product and class, acquisition and disposal dates, and relevant income or tax period if these determine applicability. Do not infer residency from nationality. Avoid asking for account numbers or tax identifiers.", "char_start": 192, "char_end": 482, "word_count": 41, "excerpt_sha256": "550c1422986fc51863c8e638293cd6ce3470bdb8752c6ea413cbbbcddd43d7d2", "source_anchor": "documents/demo/demo_tax_context.md#information-needed", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "47abd93c-adf1-5f08-a80d-7edac1cbcbc5", "document_id": "b0d468a5-e393-5621-8e32-997dc8c47118", "chunk_index": 1, "section": "Evidence limits", "content": "This fixture contains no tax rates, deduction amounts, tax liability formulas, or personal tax advice. A tax-saver name does not prove entitlement to a benefit. Withhold numerical conclusions when no reviewed applicable tax source is present.", "char_start": 504, "char_end": 746, "word_count": 36, "excerpt_sha256": "a5644abe5b0d546462f8366510dfc6985573d6b88f1a9aaef78d17cb55b52edd", "source_anchor": "documents/demo/demo_tax_context.md#evidence-limits", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "2832829b-dea1-547a-88cc-3063d8f4142c", "document_id": "b0d468a5-e393-5621-8e32-997dc8c47118", "chunk_index": 2, "section": "Escalation", "content": "Explain which context is missing. Offer a case to the demo tax specialist with the question, non-identifying context, answer ID, and source sections. Submit only after the employee explicitly confirms. A case resolution does not automatically publish new guidance.", "char_start": 763, "char_end": 1027, "word_count": 39, "excerpt_sha256": "e6d3738c1ddcc9641bb85497ce6402fc963bae1f3f7fc058c0af4a11539cd5fe", "source_anchor": "documents/demo/demo_tax_context.md#escalation", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "4882e0e7-8baf-5abe-b9bf-87b5b16efbc8", "document_id": "c6949b3b-1d04-5cbf-9b6c-987939dd7e54", "chunk_index": 0, "section": "Independent review", "content": "Received material is Draft or In review. A topic owner verifies extraction, numbers, tables, applicability, and source rights; an independent approver authorises publication. Public availability does not equal approval. The application must never invent an owner or approval timestamp.", "char_start": 188, "char_end": 473, "word_count": 39, "excerpt_sha256": "181f1e1570829e74b072fe40ed70d07041c1ad43b38cd18a365147000c269f5c", "source_anchor": "documents/demo/demo_publication.md#independent-review", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "a270ed25-589c-5fec-96af-49c16cc5271c", "document_id": "c6949b3b-1d04-5cbf-9b6c-987939dd7e54", "chunk_index": 1, "section": "Effective dates", "content": "Approval date, publication date, effective-from date, and review-due date are distinct. Future-effective guidance is scheduled and cannot support a current answer. Effective-to is an exclusive boundary in this package: a version ending 2026-07-01 is not eligible on that date.", "char_start": 495, "char_end": 771, "word_count": 39, "excerpt_sha256": "3ddb95889104bbfc965df9b64c302553f8c20c2e89d7d20f49835b44516e46b0", "source_anchor": "documents/demo/demo_publication.md#effective-dates", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "a1a0d068-60fb-5e07-9c3e-c2e1b9573e0a", "document_id": "c6949b3b-1d04-5cbf-9b6c-987939dd7e54", "chunk_index": 2, "section": "Withdrawal", "content": "Withdrawal makes the source ineligible immediately at the registry. Recheck before displaying or copying an answer. Preserve restricted historical evidence for audit, but do not reuse it as current guidance. Saved answers based on changed sources require revalidation.", "char_start": 788, "char_end": 1056, "word_count": 38, "excerpt_sha256": "58f435267d0ef3639a517e084c76d1dbd6a7ffb6e1c55674597a16c0be60ba3c", "source_anchor": "documents/demo/demo_publication.md#withdrawal", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "203fc423-fe08-574b-9051-ab4dd68dab1c", "document_id": "aeb791b1-cda4-5825-8715-3548d4c629b7", "chunk_index": 0, "section": "Future applicability", "content": "This fictional amendment is scheduled for acquisitions from 1 January 2027. It must not be applied to 2026 questions. Until activation the active terms govern.", "char_start": 180, "char_end": 339, "word_count": 25, "excerpt_sha256": "7aa23cc59763b35355ae9841c22eeb89339a7ac03caab07b13951e351d668985", "source_anchor": "documents/demo/demo_scheduled.md#future-applicability", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "d1021c3d-3575-5504-b9f7-64eec1eb14fe", "document_id": "aeb791b1-cda4-5825-8715-3548d4c629b7", "chunk_index": 1, "section": "Scheduled exit rule", "content": "For acquisitions within this future version, an illustrative exit charge of 0.25% applies within 20 calendar days and is zero after the window. It does not retroactively alter prior acquisition lots. It is provided solely to test temporal filtering.", "char_start": 365, "char_end": 614, "word_count": 39, "excerpt_sha256": "c5ba61671326ae96bfbb266bde990b6284d2a9f2ad82b1d8ea99c35d412ece97", "source_anchor": "documents/demo/demo_scheduled.md#scheduled-exit-rule", "original_source_locator": null, "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "eb3a3d1c-ab74-54fc-be2c-8941003f858d", "document_id": "1c2801e3-817d-56f0-b04e-5cffe413b3aa", "chunk_index": 0, "section": "Verified snapshot facts", "content": "The KIM dated 29 November 2024 describes SBI Gold Fund as seeking returns corresponding to SBI Gold ETF, without assurance of achieving the objective. Its allocation table gives 95–100% for SBI Gold ETF units and 0–5% for the listed liquid or money-market alternatives. The risk discussion includes possible principal loss and liquidity constraints.", "char_start": 205, "char_end": 554, "word_count": 53, "excerpt_sha256": "6d7151f441f57c8f107e57df6f2635bf3c588742357bb9ae4c1b2927ee6bc8aa", "source_anchor": "documents/reference/ref_sbi_gold.md#verified-snapshot-facts", "original_source_locator": "PDF pages 1, 2, 4", "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "531a29f5-5d98-5bf9-b9a9-1168b0ea0579", "document_id": "1c2801e3-817d-56f0-b04e-5cffe413b3aa", "chunk_index": 1, "section": "Scope of this note", "content": "See original PDF pages 1, 2 and 4. This is a limited, author-created snapshot summary. It does not establish current charges, personal suitability, bank approval, or whether later amendments exist.", "char_start": 579, "char_end": 776, "word_count": 30, "excerpt_sha256": "b2017a9347d6d690b00b36620cf6125e9c2b2319290bc989dff60d40be0c2231", "source_anchor": "documents/reference/ref_sbi_gold.md#scope-of-this-note", "original_source_locator": "PDF pages 1, 2, 4", "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "c007687d-df58-5e33-9366-1628b832fcb1", "document_id": "91fbd97d-d3fb-5bb2-b762-ea3dcbbf1dc8", "chunk_index": 0, "section": "Verified snapshot facts", "content": "The KIM dated 21 November 2025 identifies HDFC ELSS Tax Saver as an equity-linked savings scheme with a three-year statutory lock-in. It describes a predominantly equity-based objective, with no assurance of achieving that objective. It lists Regular and Direct plans with Growth and IDCW options. Its expenses section directs readers to the fund website for current expenses rather than treating historical expenses as current.", "char_start": 211, "char_end": 639, "word_count": 64, "excerpt_sha256": "2324267b9b86ad8d94c75b7be1700a7d2974e2bbed796bf4fa550c133fc652ae", "source_anchor": "documents/reference/ref_hdfc_elss.md#verified-snapshot-facts", "original_source_locator": "PDF pages 1, 2, 15, 20", "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "12121b3b-f236-5227-b1ad-40d423f831ff", "document_id": "91fbd97d-d3fb-5bb2-b762-ea3dcbbf1dc8", "chunk_index": 1, "section": "Scope of this note", "content": "See original PDF pages 1, 2, 15 and 20. This limited summary does not establish a client-specific tax benefit, suitability, current expenses, or bank approval. Check the SID, SAI and subsequent notices before publication.", "char_start": 664, "char_end": 885, "word_count": 34, "excerpt_sha256": "5169632ecb87002a36c2756f08e90425d39560c1947c39b4f22a4c0d00a711e0", "source_anchor": "documents/reference/ref_hdfc_elss.md#scope-of-this-note", "original_source_locator": "PDF pages 1, 2, 15, 20", "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "3c6e4e84-3102-50a9-8e48-fc38fa27e0c2", "document_id": "8cd378a5-644b-5027-86bb-64c686926ca6", "chunk_index": 0, "section": "Verified source facts", "content": "The Income Tax Department FAQ explains that the 2025 Act uses the tax-year concept for income from financial year 2026–27 onwards. Earlier tax years and related proceedings continue under transitional provisions of the earlier framework. Therefore, the date of a question alone is insufficient to select the tax framework.", "char_start": 216, "char_end": 538, "word_count": 49, "excerpt_sha256": "4cb548ccd0cc291ddbadf514ce5c95676f33e673ef76ee9843794a9566f7ba16", "source_anchor": "documents/reference/ref_tax_transition.md#verified-source-facts", "original_source_locator": "FAQ questions 9, 17, 21", "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "9e9092d0-9a36-5831-9f20-a3fb4766ff5f", "document_id": "8cd378a5-644b-5027-86bb-64c686926ca6", "chunk_index": 1, "section": "Scope of this note", "content": "Refer to the official FAQ questions 9, 17 and 21. This is a short summary, not a tax-rate table or a personal tax calculation. Its publication date is not established; the access timestamp is only a retrieval timestamp. A qualified owner must verify applicability and later changes.", "char_start": 563, "char_end": 845, "word_count": 47, "excerpt_sha256": "84ddf1413a77517e41d5d7fd5d1b69c7c98819d5d984f2ded5fd9f48e578e794", "source_anchor": "documents/reference/ref_tax_transition.md#scope-of-this-note", "original_source_locator": "FAQ questions 9, 17, 21", "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "14cc0423-0e6d-5ea7-a02f-3466ca2a8e7b", "document_id": "4c0dbe82-68e6-5e51-8369-d9c176eb8249", "chunk_index": 0, "section": "Verified snapshot facts", "content": "The SEBI investment-adviser master circular dated 6 February 2026 discusses responsibility for client-data security and advice when advisers use AI, disclosure of AI use, and records of advisory interactions. Its records provisions include a five-year period and longer preservation in specified dispute or regulatory circumstances.", "char_start": 223, "char_end": 555, "word_count": 45, "excerpt_sha256": "456e8250ffd7440457ccd842f1441f6c7523c9709469fafac79c49b7b14964d8", "source_anchor": "documents/reference/ref_sebi_ia.md#verified-snapshot-facts", "original_source_locator": "Printed pages 20–21", "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}, {"id": "54f7dad3-a691-5da0-b49e-9c907651d691", "document_id": "4c0dbe82-68e6-5e51-8369-d9c176eb8249", "chunk_index": 1, "section": "Scope of this note", "content": "Refer to printed pages 20–21. These provisions concern investment advisers; applicability to a retail bank depends on the entity and activity. This note is not a universal retention rule or an assessment that the application complies with law. Compliance must check applicability and subsequent changes.", "char_start": 580, "char_end": 883, "word_count": 45, "excerpt_sha256": "e7dcb49bc13cfd07df655506e093d45520d95578be9e1937b32afd2263897307", "source_anchor": "documents/reference/ref_sebi_ia.md#scope-of-this-note", "original_source_locator": "Printed pages 20–21", "content_type": "author_created_section", "embedding": null, "embedding_model": null, "embedding_dimensions": null}]$corpus$::jsonb) r
